import projectsJson from "#/data/projects.json"
import type { Project } from "#/schemas/projects"

/** In display order, from `src/data/projects.json`. */
export const projects = (projectsJson as { projects: Project[] }).projects

/** Shown in the home page stacked cards. */
export const featuredProjects: Project[] = projects.filter(project => project.featured)

/** Generated by `pnpm run media:videos`. */
export type VideoSources = {
	/** Project page. */
	full: string
	/** Short loop for cards. */
	preview: string
	poster: string
}

/** Public paths of a project's videos. */
export const getVideoSources = (slug: string): VideoSources => {
	return {
		full: `/videos/${slug}.mp4`,
		preview: `/videos/${slug}-preview.mp4`,
		poster: `/videos/${slug}.jpg`
	}
}

/** Finds a project by slug. */
export const findProject = (slug: string): Project | undefined => {
	return projects.find(project => project.slug === slug)
}
